# Installer for @TOOL@: irm @TOOL_URL@/install.ps1 | iex
# Generated by tools.klar.ws. Optional environment variables:
#   @ENV@_VERSION      version to install (default: latest)
#   @ENV@_INSTALL_DIR  target directory (default: %LOCALAPPDATA%\Programs\@TOOL@)
#   @ENV@_BASE_URL     download location (default: @TOOL_URL@)
# Runs in a script block so nothing leaks into the caller's session, and uses
# throw rather than exit, which would close the window under `irm | iex`.
& {
  $ErrorActionPreference = 'Stop'
  $ProgressPreference = 'SilentlyContinue'
  $Tool = '@TOOL@'
  $Bin = '@BIN@.exe'
  $Base = if ($env:@ENV@_BASE_URL) { $env:@ENV@_BASE_URL } else { '@TOOL_URL@' }
  $InstallDir = if ($env:@ENV@_INSTALL_DIR) { $env:@ENV@_INSTALL_DIR } else { Join-Path $env:LOCALAPPDATA "Programs\$Tool" }
  $Version = $env:@ENV@_VERSION
  if (-not $Version) { $Version = [string](Invoke-RestMethod -UseBasicParsing "$Base/latest") }
  $Version = $Version.Trim().TrimStart('v')

  $Arch = switch ([System.Runtime.InteropServices.RuntimeInformation]::OSArchitecture) {
    'X64' { 'x86_64' }
    'Arm64' { 'aarch64' }
    default { throw "Unsupported architecture: $_" }
  }
  $Asset = "$Tool-$Arch-pc-windows-msvc.zip"
  $Url = "$Base/v$Version"

  $Tmp = Join-Path ([System.IO.Path]::GetTempPath()) ("$Tool-install-" + [guid]::NewGuid())
  New-Item -ItemType Directory -Path $Tmp | Out-Null
  try {
    $Sums = Join-Path $Tmp 'checksums.txt'
    try { Invoke-WebRequest -UseBasicParsing "$Url/checksums.txt" -OutFile $Sums }
    catch { throw "$Tool $Version not found at $Url" }
    $Expected = $null
    foreach ($Line in Get-Content $Sums) {
      $Parts = $Line -split '\s+'
      if ($Parts.Count -ge 2 -and ($Parts[1] -eq $Asset -or $Parts[1] -eq "*$Asset")) { $Expected = $Parts[0]; break }
    }
    if (-not $Expected) { throw "No build of $Tool $Version for Windows $Arch" }

    $Archive = Join-Path $Tmp $Asset
    Invoke-WebRequest -UseBasicParsing "$Url/$Asset" -OutFile $Archive
    $Actual = (Get-FileHash $Archive -Algorithm SHA256).Hash.ToLowerInvariant()
    if ($Actual -ne $Expected.ToLowerInvariant()) { throw "Checksum verification failed for $Asset" }

    $Extract = Join-Path $Tmp 'x'
    Expand-Archive $Archive -DestinationPath $Extract -Force
    $Src = Get-ChildItem -Path $Extract -Recurse -File -Filter $Bin | Select-Object -First 1
    if (-not $Src) { throw "$Bin not found in $Asset" }
    New-Item -ItemType Directory -Force -Path $InstallDir | Out-Null
    Copy-Item $Src.FullName (Join-Path $InstallDir $Bin) -Force
    Write-Host "Installed $Tool $Version to $(Join-Path $InstallDir $Bin)"
    if (($env:PATH -split [System.IO.Path]::PathSeparator) -notcontains $InstallDir) {
      Write-Host "Add $InstallDir to your PATH."
    }
  } finally {
    Remove-Item -Recurse -Force $Tmp -ErrorAction SilentlyContinue
  }
}
